// FUNCTION: BFME2 0x00489800 size=149 name=?update@DozerAIUpdate@@UAE?AW4UpdateSleepTime@@XZ evidence=N:ledger tier=A
UpdateSleepTime DozerAIUpdate::update()
{
	createMachines();
	AIUpdateInterface::update();
	if (!m_object->isEffectivelyDead())
	{
		DozerTask task = getCurrentTask();
		if (task != (DozerTask)-1)
		{
			Object *target = TheGameLogic->findObjectByID(getTaskTarget(task));
			if (task == DOZER_TASK_REPAIR)
			{
				Object *dozer = m_object;
				if (!TheActionManager->canRepairObject(dozer, target, vslot143()))
					cancelTask(DOZER_TASK_REPAIR);
			}
		}
		m_dozerMachine->updateStateMachine();
	}
	return UPDATE_SLEEP_NONE;
}

// FUNCTION: BFME2 0x00489895 size=126 name=?canAcceptNewRepair@DozerAIUpdate@@UAE_NPAVObject@@@Z evidence=N:ledger tier=A
Bool DozerAIUpdate::canAcceptNewRepair(Object *obj)
{
	if (obj == 0)
		return false;
	if (getCurrentTask() == DOZER_TASK_REPAIR)
	{
		Object *current = TheGameLogic->findObjectByID(m_tasks[DOZER_TASK_REPAIR].m_targetObjectID);
		if (current != 0)
		{
			if (current == obj)
				return false;
			if (current->getTemplate()->isKindOf(KINDOF_BRIDGE_TOWER) && obj->getTemplate()->isKindOf(KINDOF_BRIDGE_TOWER))
			{
				BridgeTowerBehaviorInterface *currentTower = BridgeTowerBehavior::getBridgeTowerBehaviorInterfaceFromObject(current);
				BridgeTowerBehaviorInterface *newTower = BridgeTowerBehavior::getBridgeTowerBehaviorInterfaceFromObject(obj);
				if (currentTower == 0 || newTower == 0)
					return false;
				ObjectID newBridge = newTower->getBridgeID();
				if (currentTower->getBridgeID() == newBridge)
					return false;
			}
		}
	}
	return true;
}

// FUNCTION: BFME2 0x00489913 size=244 name=?findGoodBuildOrRepairPositionAndTarget@DozerAIUpdate@@IAEPAVObject@@PAV2@0AAVCoord3D@@@Z evidence=X:retail PE exports class Coord3D: ??0Matrix4D@@QAE@ABVCoord3D@@@Z tier=A
Object *DozerAIUpdate::findGoodBuildOrRepairPositionAndTarget(Object *me, Object *target, Coord3D &pos)
{
	if (target->getTemplate()->isKindOf(KINDOF_BRIDGE))
	{
		BridgeBehaviorInterface *bridge = BridgeBehavior::getBridgeBehaviorInterfaceFromObject(target);
		if (bridge != 0)
		{
			AIUpdateInterface *ai = me->getAI();
			Real bestDistance = 1.0e10f;
			Object *bestTower = 0;
			for (Int tower = 0; tower < 4; ++tower)
			{
				Object *candidate = TheGameLogic->findObjectByID(bridge->getTowerID((BridgeTowerType)tower));
				if (candidate != 0)
				{
					Coord3D position;
					if (findGoodBuildOrRepairPosition(me, candidate, position) && ai->isPathAvailable(&position))
					{
						Real dx = me->getPosition()->x - position.x;
						Real dy = me->getPosition()->y - position.y;
						Real distance = dx * dx + dy * dy;
						if (distance < bestDistance)
						{
							pos = position;
							bestTower = candidate;
							bestDistance = distance;
						}
					}
				}
			}
			return bestTower;
		}
	}
	findGoodBuildOrRepairPosition(me, target, pos);
	return target;
}

// FUNCTION: BFME2 0x00489A07 size=666 name=?newTask@DozerAIUpdate@@UAEXW4DozerTask@@PAVObject@@@Z evidence=N:ledger tier=A
void DozerAIUpdate::newTask(DozerTask task, Object *target)
{
	if (target == 0)
		return;
	if (task == DOZER_TASK_BUILD || task == DOZER_TASK_REPAIR)
	{
		if (isTaskPending(task) == true)
			cancelTask(task);

		Object *me = m_object;

		if (g_bfmeDockingDesyncLog)
		{
			if (theLogicRandomLogFile != 0)
				theLogicRandomLogFile->addLine("DockingDesync(DOZER) BEGIN: Object %s(%d) with target %s(%d) at %g,%g,%g",
					me->getTemplate()->getName().str(), me->getID(), target->getTemplate()->getName().str(), target->getID(),
					me->getPosition()->x, me->getPosition()->y, me->getPosition()->z);
			g_bfmeDockingTraceActive = true;
		}

		Coord3D position;
		target = findGoodBuildOrRepairPositionAndTarget(me, target, position);
		if (target == 0)
		{
			if (g_bfmeDockingDesyncLog)
			{
				if (theLogicRandomLogFile != 0)
					theLogicRandomLogFile->addLine("DockingDesync(DOZER) END: Object %s(%d) with no target found docking position %g,%g,%g",
						me->getTemplate()->getName().str(), me->getID(), position.x, position.y, position.z);
				g_bfmeDockingTraceActive = false;
			}
			return;
		}

		if (g_bfmeDockingDesyncLog)
		{
			if (theLogicRandomLogFile != 0)
				theLogicRandomLogFile->addLine("DockingDesync(DOZER) END: Object %s(%d) with target %s(%d) found docking position %g,%g,%g",
					me->getTemplate()->getName().str(), me->getID(), target->getTemplate()->getName().str(), target->getID(),
					position.x, position.y, position.z);
			g_bfmeDockingTraceActive = false;
		}

		if (task == DOZER_TASK_BUILD)
			target->setBuilder(me);

		m_dockPoints[task][DOZER_DOCK_POINT_START].m_valid = true;
		m_dockPoints[task][DOZER_DOCK_POINT_START].m_position = position;
		m_dockPoints[task][DOZER_DOCK_POINT_ACTION].m_valid = true;
		m_dockPoints[task][DOZER_DOCK_POINT_ACTION].m_position = position;
		Coord3D offset;
		offset.x = position.x - target->getPosition()->x;
		offset.y = position.y - target->getPosition()->y;
		offset.z = 0.0f;
		offset.normalize();
		Real step = 5 * 10.0f;
		Coord3D shift;
		shift.set(offset.x * step, offset.y * step, offset.z * step);
		position.add(&shift);
		m_dockPoints[task][DOZER_DOCK_POINT_END].m_valid = true;
		m_dockPoints[task][DOZER_DOCK_POINT_END].m_position = position;
	}

	m_tasks[task].m_targetObjectID = target->getID();
	m_tasks[task].m_startFrame = TheGameLogic->getFrame();

	m_dozerMachine->resetToDefaultState();
}

// FUNCTION: BFME2 0x00489CA1 size=104 name=?onDelete@DozerAIUpdate@@UAEXXZ evidence=N:ledger tier=A
void DozerAIUpdate::onDelete()
{
	for (Int task = 0; task < 3; ++task)
	{
		if (isTaskPending((DozerTask)task))
			cancelTask((DozerTask)task);
	}
	for (Int task = 0; task < 3; ++task)
	{
		Object *target = TheGameLogic->findObjectByID(m_tasks[task].m_targetObjectID);
		if (target != 0)
		{
			// Model condition 69 (ACTIVELY_BEING_CONSTRUCTED).
			target->clearModelConditionState(2 * 32 + 5);
		}
	}
	finishBuildingSound();
}

