// FUNCTION: BFME2 0x00489DE3 size=75 name=?makePhantomStructureInert@DozerAIUpdate@@QAEXXZ evidence=N:ledger tier=A
void DozerAIUpdate::makePhantomStructureInert()
{
	if (m_phantomStructureID != INVALID_ID)
	{
		Object *phantom = TheGameLogic->findObjectByID(m_phantomStructureID);
		if (phantom == 0)
		{
			m_phantomStructureID = INVALID_ID;
		}
		else
		{
			phantom->setEffectivelyDead(true);
			if (phantom->m_isRegisteredInWorld)
				phantom->rva0028BAC0();
			phantom->m_isPhantomStructureInert = true;
		}
	}
}

// FUNCTION: BFME2 0x00489E2E size=99 name=?makePhantomStructureNotInert@DozerAIUpdate@@QAEXXZ evidence=N:ledger tier=A
void DozerAIUpdate::makePhantomStructureNotInert()
{
	if (m_phantomStructureID != INVALID_ID)
	{
		if (m_object != 0)
		{
			Player *owner = m_object->getControllingPlayer();
			if (owner != 0)
				owner->removePhantomStructureID(m_phantomStructureID);
		}
		Object *phantom = TheGameLogic->findObjectByID(m_phantomStructureID);
		if (phantom == 0)
		{
			m_phantomStructureID = INVALID_ID;
		}
		else
		{
			phantom->m_isPhantomStructureInert = false;
			phantom->rva0028DCC4();
			phantom->setEffectivelyDead(false);
		}
	}
}

