// FUNCTION: BFME2 0x00489F7D size=477 name=?createPhantomStructure@DozerAIUpdate@@UAEXPBVThingTemplate@@PAVPlayer@@PBVCoord3D@@M@Z evidence=X:retail PE exports class Coord3D: ??0Matrix4D@@QAE@ABVCoord3D@@@Z tier=A

// FUNCTION: BFME2 0x0048A15A size=579 name=?makePhantomStructureReal@DozerAIUpdate@@UAEXXZ evidence=N:ledger tier=A

// FUNCTION: BFME2 0x0048A3B9 size=292 name=?Rva0048A3B9Do@@YAXPAVObject@@0_N@Z evidence=?:placeholder tier=A

// FUNCTION: BFME2 0x0048A4DD size=449 name=?update@DozerActionPickActionPosState@@UAE?AW4StateReturnType@@XZ evidence=N:ledger tier=A
StateReturnType DozerActionPickActionPosState::update()
{
	StateMachine *machine = getMachine();
	Object *dozer = machine->getOwner();
	AIUpdateInterface *ai = dozer->getAI();
	if (ai == 0)
		return STATE_FAILURE;
	DozerAIInterface *dozerAI = ai->getDozerAIInterface();
	if (dozerAI == 0)
		return STATE_FAILURE;
	Object *goalObject = TheGameLogic->findObjectByID(dozerAI->getTaskTarget((DozerTask)m_task));
	if (goalObject == 0)
	{
		goalObject = dozerAI->getPhantomStructure2();
		if (goalObject == 0)
		{
			getMachine()->setGoalObject(0);
			dozerAI->cancelTask((DozerTask)m_task);
			return STATE_FAILURE;
		}
	}
	Coord3D goalPos;
	const Coord3D *pos = dozerAI->getDockPoint((DozerTask)m_task, DOZER_DOCK_POINT_START);
	if (pos != 0)
		goalPos = *pos;
	else
	{
		Coord2D v;
		v.x = dozer->getPosition()->x - goalObject->getPosition()->x;
		v.y = dozer->getPosition()->y - goalObject->getPosition()->y;
		Real radius = goalObject->getGeometryInfo()->m_minorRadius;	// Object +0xBC: Zero Hour reads getBoundingSphereRadius() here
		FindPositionOptions options;
		options.minRadius = radius;
		options.maxRadius = radius;
		options.startAngle = v.toAngle();
		if (ThePartitionManager->findPositionAround(goalObject->getPosition(), &options, &goalPos) == FALSE)
			goalPos = *goalObject->getPosition();
		else if (g_bfmeCritterDesyncLog && theLogicRandomLogFile != 0)
			theLogicRandomLogFile->addLine("\t\t  DozerActionPickActionPosState::update() goalPos is uninitialized");
		ai->ignoreObstacle(goalObject);
	}
	if (g_bfmeCritterDesyncLog && theLogicRandomLogFile != 0)
		theLogicRandomLogFile->addLine("\t\t  DozerActionPickActionPosState::update(), moving to goalPos %.03f, %.03f", goalPos.x, goalPos.y);
	machine->setGoalObject(goalObject);
	machine->setGoalPosition(&goalPos, 3.4028235e+38f);
	ai->ignoreObstacle(goalObject);
	ai->aiMoveToPosition(&goalPos, CMD_FROM_AI);
	return STATE_SUCCESS;
}

// FUNCTION: BFME2 0x0048A69E size=2028 name=?update@DozerActionDoActionState@@UAE?AW4StateReturnType@@XZ evidence=N:ledger tier=A

// FUNCTION: BFME2 0x0048AE8A size=60 name=?cancelTask@DozerAIUpdate@@UAEXW4DozerTask@@@Z evidence=N:ledger tier=A

// FUNCTION: BFME2 0x0048AEC6 size=69 name=?internalCancelTask@DozerAIUpdate@@UAEXW4DozerTask@@@Z evidence=N:ledger tier=A
void DozerAIUpdate::internalCancelTask(DozerTask task)
{
	internalTaskCompleteOrCancelled(task);
	m_tasks[task].m_targetObjectID = INVALID_ID;
	m_tasks[task].m_startFrame = 0;
	for (Int point = 0; point < 3; ++point)
		m_dockPoints[task][point].m_valid = false;
	m_object->getAI()->aiIdle(CMD_FROM_AI);
}

